"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   sax: () => (/* binding */ sax)\n/* harmony export */ });\nconst sax = {\n    \"content\": [\n        {\n            \"content\": \"# Mastering Solved LeetCode Problems\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"## Introduction to Solving Problems on LeetCode\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"LeetCode is a widely popular platform for coding enthusiasts to hone their problem-solving skills. The platform offers a variety of problems that help in improving one's coding skills and prepare for coding interviews. This article is designed to guide you through solving easy LeetCode problems and making the most out of the platform.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"### Understanding Problem Statements\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"The first step in solving any LeetCode problem is to thoroughly understand the problem statement. Read the description carefully and identify the inputs, outputs, and constraints given. Misinterpreting the problem can lead to incorrect solutions, so it's crucial to pay attention to every detail in the problem statement.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"### Basic Coding Skills\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"#### Syntax and Semantics\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"A solid understanding of the syntax and semantics of your chosen programming language is fundamental. Syntax refers to the rules that define the combinations of symbols that are considered to be a correctly structured program while semantics refers to the meaning of the constructs in the language.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"#### Basic Data Structures\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"##### Arrays\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"An array is a collection of items stored at contiguous memory locations. The idea is to store multiple items of the same type together, making it easier to calculate the position of each element by simply adding an offset to a base value.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"```python\\n# Sample Code: Reverse an Array\\narr = [1, 2, 3, 4, 5]\\nreversed_arr = arr[::-1]\\nprintf(reversed_arr) # Output: [5, 4, 3, 2, 1]\\n```\",\n            \"type\": \"code\",\n            \"programming_language\": \"python\"\n        },\n        {\n            \"content\": \"##### Strings\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"Strings are arrays of characters and are one of the most commonly used data structures. Many problems on LeetCode involve manipulating strings.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"##### Linked Lists\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"A linked list is a linear data structure, in which the elements are not stored at contiguous memory locations. The elements in a linked list are linked using pointers.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"```python\\n# Sample Code: Define a Node of a Linked List\\nclass ListNode:\\n    def __init__(self, val=0, next=None):\\n        self.val = val\\n        self.next = next\\n\\n# Create a simple linked list 1 -> 2 -> 3\\nnode3 = ListNode(3)\\nnode2 = ListNode(2, node3)\\nnode1 = ListNode(1, node2)\\nprintf(node1.val, node1.next.val, node1.next.next.val) # Output: 1 2 3\\n```\",\n            \"type\": \"code\",\n            \"programming_language\": \"python\"\n        },\n        {\n            \"content\": \"#### Basic Algorithms\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"##### Sorting\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"Sorting is a common operation in many problems. Understanding various sorting algorithms and their complexities is crucial.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"```python\\n# Sample Code: Bubble Sort\\narr = [64, 34, 25, 12, 22, 11, 90]\\ndef bubble_sort(arr):\\n    n = len(arr)\\n    for i in range(n):\\n        for j in range(0, n-i-1):\\n            if arr[j] > arr[j+1]:\\n                arr[j], arr[j+1] = arr[j+1], arr[j]\\nbubble_sort(arr)\\nprintf('Sorted array is:', arr) # Output: [11, 12, 22, 25, 34, 64, 90]\\n```\",\n            \"type\": \"code\",\n            \"programming_language\": \"python\"\n        },\n        {\n            \"content\": \"##### Searching\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"Searching algorithms are used to find the position of an element in a data structure. Examples include linear search and binary search.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"```python\\n# Sample Code: Binary Search\\narr = [2, 3, 4, 10, 40]\\nx = 10\\ndef binary_search(arr, x):\\n    l, r = 0, len(arr)-1\\n    while l <= r:\\n        mid = l + (r - l) // 2\\n        if arr[mid] == x:\\n            return mid\\n        elif arr[mid] < x:\\n            l = mid + 1\\n        else:\\n            r = mid - 1\\n    return -1\\nresult = binary_search(arr, x)\\nprintf('Element is present at index', result) # Output: Element is present at index 3\\n```\",\n            \"type\": \"code\",\n            \"programming_language\": \"python\"\n        },\n        {\n            \"content\": \"## Solving Easy LeetCode Problems\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"### Common Easy Problem Categories\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"#### Two Pointers\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"The two-pointer technique is used for problems involving linear data structures like arrays or linked lists. The idea is to use two pointers to traverse the structure from both ends or from the same end to solve the problem more efficiently.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"```python\\n# Example: Move Zeroes\\n# Given an array nums, write a function to move all 0's to the end while maintaining relative order of non-zero elements.\\ndef move_zeroes(nums):\\n    lastNonZeroFoundAt = 0\\n    for cur in range(len(nums)):\\n        if nums[cur] != 0:\\n            nums[lastNonZeroFoundAt], nums[cur] = nums[cur], nums[lastNonZeroFoundAt]\\n            lastNonZeroFoundAt += 1\\nnums = [0, 1, 0, 3, 12]\\nmove_zeroes(nums)\\nprintf(nums) # Output: [1, 3, 12, 0, 0]\\n```\",\n            \"type\": \"code\",\n            \"programming_language\": \"python\"\n        },\n        {\n            \"content\": \"#### Hashing\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"Hashing is a technique used to map data of arbitrary size to fixed-size values. Hash maps or dictionaries are very useful for problems requiring efficient look-up, insertion, and deletion operations.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"```python\\n# Example: Two Sum\\n# Given an array of integers nums and an integer target, return indices of the two numbers such that they add up to target.\\ndef two_sum(nums, target):\\n    hash_map = {}\\n    for i, num in enumerate(nums):\\n        if target - num in hash_map:\\n            return [hash_map[target - num], i]\\n        hash_map[num] = i\\nnums = [2, 7, 11, 15]\\ntarget = 9\\nresult = two_sum(nums, target)\\nprintf(result) # Output: [0, 1]\\n```\",\n            \"type\": \"code\",\n            \"programming_language\": \"python\"\n        },\n        {\n            \"content\": \"#### Simple Math\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"Some problems require simple mathematical calculations. These problems are straightforward but require attention to detail to avoid off-by-one errors or rounding issues.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"```python\\n# Example: Add Digits\\n# Given an integer num, repeatedly add all its digits until the result has only one digit.\\ndef add_digits(num):\\n    while num >= 10:\\n        num = sum(map(int, str(num)))\\n    return num\\nnumber = 38\\nresult = add_digits(number)\\nprintf(result) # Output: 2\\n```\",\n            \"type\": \"code\",\n            \"programming_language\": \"python\"\n        },\n        {\n            \"content\": \"### Approaches and Tricks for Easy Problems\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"#### Brute Force Approach\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"The brute force approach is straightforward and checks all possible solutions. While it may not be the most efficient method, it is useful for understanding the problem and establishing a base for more optimized solutions.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"#### Using Hash Maps\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"Hash maps are powerful tools for reducing the time complexity of problems that involve searching or matching elements. They allow for O(1) average time complexity for lookups.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"#### Simplifying the Problem\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"Breaking down a complex problem into simpler sub-problems can make it easier to solve. Look for patterns or repetitive tasks that can be modularized.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"### Practice Easy Problems\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"#### Arrays and Strings\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"Practice problems involving arrays and strings to improve your efficiency in handling these basic data structures.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"```python\\n# Example: Reverse String\\n# Write a function that reverses a string. The input string is given as an array of characters.\\ndef reverse_string(s):\\n    s.reverse()\\nstring = ['h', 'e', 'l', 'l', 'o']\\nreverse_string(string)\\nprintf(string) # Output: ['o', 'l', 'l', 'e', 'h']\\n```\",\n            \"type\": \"code\",\n            \"programming_language\": \"python\"\n        },\n        {\n            \"content\": \"#### Linked Lists\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"Linked lists problems often involve reversing, merging, or finding elements. Practice these to get comfortable with pointer manipulations.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"```python\\n# Example: Merge Two Sorted Lists\\n# Merge two sorted linked lists and return it as a new sorted list.\\ndef merge_two_lists(l1, l2):\\n    sentinel = ListNode(0)\\n    tail = sentinel\\n    while l1 and l2:\\n        if l1.val < l2.val:\\n            tail.next = l1\\n            l1 = l1.next\\n        else:\\n            tail.next = l2\\n            l2 = l2.next\\n        tail = tail.next\\n    tail.next = l1 if l1 else l2\\n    return sentinel.next\\nlist1 = ListNode(1, ListNode(2, ListNode(4)))\\nlist2 = ListNode(1, ListNode(3, ListNode(4)))\\nresult = merge_two_lists(list1, list2)\\nwhile result:\\n    print(result.val, end=' ')\\n    result = result.next\\n# Output: 1 1 2 3 4 4\\n```\",\n            \"type\": \"code\",\n            \"programming_language\": \"python\"\n        },\n        {\n            \"content\": \"#### Trees\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"Tree problems often involve traversals like in-order, pre-order, and post-order. Start with simple ones and gradually move to problems involving tree manipulations.\",\n            \"type\": \"text\"\n        },\n        {\n            \"content\": \"```python\\n# Example: Max Depth of Binary Tree\\n# Given a binary tree, find its maximum depth.\\ndef max_depth(root):\\n    if not root:\\n        return 0\\n    left_depth = max_depth(root.left)\\n    right_depth = max_depth(root.right)\\n    return max(left_depth, right_depth) + 1\\nclass TreeNode:\\n    def __init__(self, val=0, left=None, right=None):\\n        self.val = val\\n        self.left = left\\n        self.right = right\\ntree = TreeNode(3, TreeNode(9), TreeNode(20, TreeNode(15), TreeNode(7)))\\nresult = max_depth(tree)\\nprintf(result) # Output: 3\\n```\",\n            \"type\": \"code\",\n            \"programming_language\": \"python\"\n        }\n    ]\n};\n\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/app/tt.js\n");

